`timescale 1ns/1ps
module memory_access_tb;logic[1:0]MemRW,AddrLSB;logic[2:0]Funct3;logic[31:0]StoreData,ReadData,WriteData,LoadData;logic[3:0]ByteEnable;memory_access dut(.*);string f;integer fd,rc,id,mr,ft,off,total=0,pass=0;logic[31:0]sd,rd,ew,el;integer eb;
initial begin if(!$value$plusargs("VECTORS=%s",f))f="vectors/sample/memory_access_sample.txt";fd=$fopen(f,"r");while(!$feof(fd))begin rc=$fscanf(fd,"%d %b %b %b %h %h %h %b %h\n",id,mr,ft,off,sd,rd,ew,eb,el);if(rc==9)begin MemRW=mr[1:0];Funct3=ft[2:0];AddrLSB=off[1:0];StoreData=sd;ReadData=rd;#1;total++;if(WriteData===ew&&ByteEnable===eb[3:0]&&LoadData===el)pass++;else $display("FAIL %0d W=%h/%h BE=%b/%b L=%h/%h",id,WriteData,ew,ByteEnable,eb,LoadData,el);end end $display("Passed: %0d Failed: %0d Total: %0d",pass,total-pass,total);if(pass==total)$finish(0);else $finish(1);end endmodule
